import type { DensityTargets } from './schema';

// ============================================================================
// SHA-256 (FIPS 180-4)
// ============================================================================

/** The 64 round constants: the first 32 bits of the fractional parts of the cube roots of the first 64 primes. */
const K: readonly number[] = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

/** The initial hash value: the first 32 bits of the fractional parts of the square roots of the first 8 primes. */
const H0: readonly number[] = [
  0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
];

/** Thrown for a value that has no UTF-8 or canonical-JSON form (a lone surrogate, `NaN`, a function…). */
export class DensityHashError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DensityHashError';
  }
}

/**
 * UTF-8 bytes of `text`. A lone surrogate has no UTF-8 form, so it is refused
 * rather than replaced: two different strings must never hash alike.
 */
function utf8Bytes(text: string): number[] {
  const out: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      const next = i + 1 < text.length ? text.charCodeAt(i + 1) : -1;
      if (next < 0xdc00 || next > 0xdfff) {
        throw new DensityHashError(`lone high surrogate at index ${i} has no UTF-8 form`);
      }
      cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
      i++;
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      throw new DensityHashError(`lone low surrogate at index ${i} has no UTF-8 form`);
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

function rotr(x: number, n: number): number {
  return (x >>> n) | (x << (32 - n));
}

/** SHA-256 of `text` encoded as UTF-8, as 64 lower-case hex digits. */
export function sha256DensityHex(text: string): string {
  const bytes = utf8Bytes(text);
  const bitLength = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  // The 64-bit big-endian length. A JS string cannot reach 2^53 bits, so the
  // high word is computed by division rather than by a 64-bit shift.
  const high = Math.floor(bitLength / 0x100000000);
  const low = bitLength >>> 0;
  bytes.push(
    (high >>> 24) & 0xff,
    (high >>> 16) & 0xff,
    (high >>> 8) & 0xff,
    high & 0xff,
    (low >>> 24) & 0xff,
    (low >>> 16) & 0xff,
    (low >>> 8) & 0xff,
    low & 0xff
  );

  const h = H0.slice();
  const w = new Array<number>(64);
  for (let offset = 0; offset < bytes.length; offset += 64) {
    for (let t = 0; t < 16; t++) {
      const j = offset + t * 4;
      w[t] = ((bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (hh + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      hh = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }
    h[0] = (h[0] + a) >>> 0;
    h[1] = (h[1] + b) >>> 0;
    h[2] = (h[2] + c) >>> 0;
    h[3] = (h[3] + d) >>> 0;
    h[4] = (h[4] + e) >>> 0;
    h[5] = (h[5] + f) >>> 0;
    h[6] = (h[6] + g) >>> 0;
    h[7] = (h[7] + hh) >>> 0;
  }
  return h.map((word) => ('00000000' + word.toString(16)).slice(-8)).join('');
}

// ============================================================================
// RFC 8785 canonical JSON
// ============================================================================

/**
 * The RFC 8785 serialization of `value`: object keys ordered by UTF-16 code
 * units, numbers in the ECMAScript `Number.prototype.toString` form (which is
 * what `JSON.stringify` emits for a finite number, `-0` included as `0`),
 * strings escaped as `JSON.stringify` escapes them, and no whitespace.
 *
 * Refused, with {@link DensityHashError}: a non-finite number, a bigint, a
 * function, a symbol, `undefined` as a top-level value or array element, and a
 * string holding a lone surrogate (RFC 8785 requires I-JSON). An object
 * property whose value is `undefined` is omitted, as `JSON.stringify` omits
 * it — a parsed JSON document never holds one.
 */
export function canonicalDensityJson(value: unknown): string {
  return serialize(value, '$', new Set<object>());
}

/** Only what JSON.parse can produce has a canonical form: plain objects and dense arrays. */
function serialize(value: unknown, path: string, open: Set<object>): string {
  if (value === null) return 'null';
  switch (typeof value) {
    case 'boolean':
      return value ? 'true' : 'false';
    case 'number':
      if (!Number.isFinite(value)) {
        throw new DensityHashError(`${path}: ${String(value)} has no JSON form`);
      }
      return JSON.stringify(value);
    case 'string':
      // Refuse a lone surrogate; JSON.stringify would escape it as \udXXX,
      // which I-JSON (and so RFC 8785) does not allow.
      utf8Bytes(value);
      return JSON.stringify(value);
    case 'object': {
      if (open.has(value)) throw new DensityHashError(`${path}: a cycle has no JSON form`);
      open.add(value);
      try {
        if (Array.isArray(value)) {
          const parts: string[] = [];
          for (let i = 0; i < value.length; i++) {
            if (!(i in value))
              throw new DensityHashError(`${path}[${i}]: an array hole has no JSON form`);
            parts.push(serialize(value[i], `${path}[${i}]`, open));
          }
          return '[' + parts.join(',') + ']';
        }
        const proto = Object.getPrototypeOf(value) as unknown;
        if (proto !== Object.prototype && proto !== null) {
          throw new DensityHashError(`${path}: only a plain object has a canonical JSON form`);
        }
        return serializeRecord(value as Record<string, unknown>, path, open);
      } finally {
        open.delete(value);
      }
    }
    default:
      throw new DensityHashError(`${path}: a ${typeof value} has no JSON form`);
  }
}

function serializeRecord(record: Record<string, unknown>, path: string, open: Set<object>): string {
  // Default sort compares UTF-16 code units, which is exactly RFC 8785 section 3.2.3.
  const keys = Object.keys(record)
    .filter((k) => record[k] !== undefined)
    .sort();
  return (
    '{' +
    keys
      .map((k) => {
        utf8Bytes(k);
        return JSON.stringify(k) + ':' + serialize(record[k], `${path}.${k}`, open);
      })
      .join(',') +
    '}'
  );
}

/** SHA-256 hex of the RFC 8785 form of `value` — the hash every density id-by-content uses. */
export function hashDensityCanonical(value: unknown): string {
  return sha256DensityHex(canonicalDensityJson(value));
}

/**
 * The `textHash` of an item: SHA-256 hex of its whitespace-collapsed text. It
 * lets two captures say whether a block's text changed (`invariance`) without
 * either keeping the text.
 */
export function densityTextHash(collapsedText: string): string {
  return sha256DensityHex(collapsedText);
}

/** `targetsHash`: the hash of the whole parsed targets document, carried in every report's provenance. */
export function densityTargetsHash(targets: DensityTargets): string {
  return hashDensityCanonical(targets);
}

/**
 * `asksHash`: the hash of the canonical asks — each role's name and its parsed
 * asks, in document order. A `review` block whose `asksHash` differs from this
 * reviewed a different set of asks.
 */
export function densityAsksHash(targets: DensityTargets): string {
  return hashDensityCanonical(targets.roles.map((r) => ({ role: r.role, asks: r.asks })));
}
